}
from collections import defaultdict
for a,pa in objs.items():
 for b,pb in objs.items():
  if a>=b: continue
  cnt=defaultdict(list)
  for x in pa:
   for y in pb:
    d=(x[0]-y[0],x[1]-y[1]) # translation b relative a for alignment
    cnt[d].append((x,y))
  m=max(map(len,cnt.values()))
  print(a,b,'max',m,[(d,v) for d,v in cnt.items() if len(v)==m])

