# offsets of b relative a; list marker intersections and color collisions
for a in fills:
 for b in list(fills)[list(fills).index(a)+1:]:
  cands=defaultdict(list)
  for p in marks[a]:
   for q in marks[b]: cands[(p[0]-q[0],p[1]-q[1])].append((p,q))
  maxm=max(map(len,cands.values()))
  best=[]
  for d, pairs in cands.items():
   if len(pairs)>=2:
    coll=len(fills[a]&{(r+d[0],c+d[1]) for r,c in fills[b]})
    best.append((d,len(pairs),coll,pairs))
  if best: print(a,b,best)

