spares={'5':{(0,2),(2,3)},'4':{(-1,3),(4,4)}}
for n,ps in spares.items():
 for p in ps:
  gp=(positions[n][0]+p[0],positions[n][1]+p[1])
  for q in marks['9a']:
   d=(gp[0]-q[0],gp[1]-q[1])
   coll=len(occ & shifted(fills['9a'],d))
   if coll==0: print(n,p,'9aport',q,'9a anchor',d,'collision',coll)

