for p4 in marks['4']-used4:
 for q9 in marks['9a']:
  a9=(posbase['4'][0]+p4[0]-q9[0],posbase['4'][1]+p4[1]-q9[1])
  if occbase & shifted(fills['9a'],a9): continue
  # now consider 7/9b group attaches via spare 9a mark, spare 7 port
  for p7 in {(3,1),(4,1)}:
   for q9bpin in marks['9a']-{q9}:
    glob= (a9[0]+q9bpin[0],a9[1]+q9bpin[1])
    a7=(glob[0]-p7[0],glob[1]-p7[1]); a9b=(a7[0],a7[1]-3)
    coll=len(occbase & shifted(fills['9a'],a9)) + len((occbase|shifted(fills['9a'],a9)) & shifted(fills['7'],a7)) + len((occbase|shifted(fills['9a'],a9)|shifted(fills['7'],a7)) & shifted(fills['9b'],a9b))
    if coll: continue
    allpos={**posbase,'9a':a9,'7':a7,'9b':a9b}
