core_pos={'4':(12,11),'5':(15,8),'6':(15,3),'8':(15,1)}
corefill=set().union(*(shifted(fills[n],p) for n,p in core_pos.items()))
coremarks={n:shifted(marks[n],p) for n,p in core_pos.items()}
coremarkunion=set().union(*coremarks.values())
# enumerate placements within grid; require no colors overlap, marker not on color
sol=[]
for ar in range(0,20):
 for ac in range(0,20):
  pa=(ar,ac); fa=shifted(fills['9a'],pa); ma=shifted(marks['9a'],pa)
  if fa&corefill or ma&corefill: continue
  for br in range(0,20):
   for bc in range(3,26):
    p7=(br,bc); p9b=(br,bc-3)
    f7=shifted(fills['7'],p7); f9b=shifted(fills['9b'],p9b)
    if f7&corefill or f9b&corefill or f7&fa or f9b&fa or f7&f9b: continue
    m7=shifted(marks['7'],p7); m9b=shifted(marks['9b'],p9b)
    if (m7|m9b)&(corefill|fa) or ma&(corefill|f7|f9b): continue
    # score marker point collisions across separately placed objects; 7/9b pair always 2
    mset={'core':coremarkunion,'9a':ma,'7':m7,'9b':m9b}
    pairs=[]
    for i,x in enumerate(mset):
     for y in list(mset)[i+1:]: pairs.append((x,y,len(mset[x]&mset[y])))
    sc=sum(k for _,_,k in pairs)
    # bounding box colored cells
    allc=corefill|fa|f7|f9b
    rr=[r for r,c in allc]; cc2=[c for r,c in allc]
    area=(max(rr)-min(rr)+1)*(max(cc2)-min(cc2)+1)
    sol.append((sc,area,pa,p7,p9b,pairs))
sol_sorted=sorted(sol,key=lambda x:(-x[0],x[1]))
